          type: "plain",
          md: "สายดินคือ **ทางหนีไฟที่เตรียมไว้** ถ้าสายไฟในเครื่องใช้ไฟฟ้ารั่วมาแตะโครงโลหะ กระแสจะไหลกลับทางสายดินที่ทางสะดวก แทนที่จะไหลผ่านคนที่จับเครื่อง และเพราะทางนี้ไหลสะดวก กระแสจึงมากพอให้เบรกเกอร์ตัดทันที บ้านในไทยต่อสายดินแบบที่เรียกว่า **TN-C-S** ขั้นนี้อธิบายว่าสายดินเดินจากตู้ไฟไปทุกจุดอย่างไร",
