          alt: "สองแผง แผงบน ผิด หม้อแปลงลงดิน 5 Ω สาย L ผ่าน MCB 16 A ไปโครงเครื่องที่มีไฟรั่ว โครงต่อหลักดินแยก 10 Ω กระแสกลับทางดิน กล่องผลลัพธ์ 230 หาร 10 บวก 5 ได้ 15.3 A น้อยกว่า 16 A ไม่ตัด โครงมีแรงดัน 153 V อันตราย แผงล่าง ถูก สาย PE จากโครงกลับตู้เมนต่อกับ PEN ลูปประมาณ 1 Ω กระแสประมาณ 230 A มากกว่า 10 คูณ 16 เท่ากับ 160 A ตัดทันทีน้อยกว่า 0.1 วินาที",
